LANGS = ['zh-Hans', 'cs', 'da', 'de', 'es', 'fr', 'nl', 'pt-PT', 'pt-BR', 'ru']
out = {}
for key, values in T.items():
    assert len(values) == 10, key
    row = dict(zip(LANGS, values))
    row['fr-CA'] = row['fr']
    out[key] = row
json.dump(out, open('/tmp/i18n/manual.json', 'w'), ensure_ascii=False, indent=1)
print(len(out))
